package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="dizimista",schema="adm_eclesial") public class Dizimista { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="pessoa_id",nullable=false) Long pessoaId; @Column(name="organizacao_eclesial_id",nullable=false) Long organizacaoEclesialId; @Column(name="data_inicio",nullable=false) LocalDate dataInicio; @Column(name="data_fim") LocalDate dataFim; @Column(nullable=false) boolean ativo; @Column(columnDefinition="text") String observacao; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public Long getPessoaId(){return pessoaId;} public Long getOrganizacaoEclesialId(){return organizacaoEclesialId;} public LocalDate getDataInicio(){return dataInicio;} public LocalDate getDataFim(){return dataFim;} public boolean getAtivo(){return ativo;} public String getObservacao(){return observacao;} public void setPessoaId(Long v){pessoaId=v;} public void setOrganizacaoEclesialId(Long v){organizacaoEclesialId=v;} public void setDataInicio(LocalDate v){dataInicio=v;} public void setDataFim(LocalDate v){dataFim=v;} public void setAtivo(boolean v){ativo=v;} public void setObservacao(String v){observacao=v;} }